const d = msg.payload;
if (!d || d.token !== 'C202-KEL2-2026-AUTH') {
    node.warn('Paket ditolak: token tidak valid');
    return null;
}

const parts = msg.topic.split('/');
const roomId = (parts[2] || 'C202').toUpperCase();

let rooms = flow.get('rooms') || {};
rooms[roomId] = {
    id: roomId,
    status: d.status || 'KOSONG',
    suhu: Number(d.suhu ?? 0).toFixed(1),
    lux: Math.round(d.lux ?? 0),
    pwm: Math.round(d.pwm ?? 0),
    ac: (d.ac === 1 || d.ac === true || d.ac === 'ON') ? 'ON' : 'OFF',
    kwh_hemat: Number(d.kwh_hemat ?? d.hemat_kwh ?? 0).toFixed(3),
    hemat_rp: Math.round(d.hemat_rp ?? 0),
    hemat_persen: Number(d.hemat_persen ?? 0).toFixed(1),
    raw: d
};
flow.set('rooms', rooms);

const list = Object.values(rooms).sort((a, b) => a.id.localeCompare(b.id));
const totalRp = list.reduce((s, r) => s + Number(r.hemat_rp), 0);
const totalKwh = list.reduce((s, r) => s + Number(r.kwh_hemat), 0).toFixed(3);
const aktifCount = list.filter(r => r.status === 'OKUPASI').length;
const selected = (flow.get('selected_room') || list[0].id).toUpperCase();
flow.set('selected_room', selected);

const outOverview = {
    payload: {
        rooms: list,
        selected: selected,
        total_ruang: list.length,
        aktif: aktifCount,
        total_rp: totalRp.toLocaleString('id-ID'),
        total_kwh: totalKwh
    }
};

let outDetail = null;
if (roomId === selected) {
    outDetail = { payload: rooms[roomId] };
}

return [outOverview, outDetail];

const chosen = String(msg.payload).toUpperCase();
flow.set('selected_room', chosen);

const rooms = flow.get('rooms') || {};
const list = Object.values(rooms).sort((a, b) => a.id.localeCompare(b.id));
const totalRp = list.reduce((s, r) => s + Number(r.hemat_rp), 0);
const totalKwh = list.reduce((s, r) => s + Number(r.kwh_hemat), 0).toFixed(3);
const aktifCount = list.filter(r => r.status === 'OKUPASI').length;

const outOverview = {
    payload: {
        rooms: list,
        selected: chosen,
        total_ruang: list.length,
        aktif: aktifCount,
        total_rp: totalRp.toLocaleString('id-ID'),
        total_kwh: totalKwh
    }
};

const outDetail = rooms[chosen] ? { payload: rooms[chosen] } : null;
return [outOverview, outDetail];

const r = msg.payload;
if (!r) return null;

return [
    { payload: `RUANG ${r.id} — ${r.status} (AC: ${r.ac})` },
    { payload: Number(r.suhu) },
    { payload: Number(r.lux) },
    { payload: Number(r.pwm) },
    { payload: Number(r.suhu), topic: `Suhu ${r.id}` }
];
